svg.script:
const svg = document.documentElement;
const capa = document.getElementById('pelos');
// Negros, blancos y cafés (cada color tiene la misma probabilidad de salir)
const colores = ['#000000', '#1a1a1a', '#ffffff', '#f2f2f2', '#6d4c41', '#8d5a3c', '#a0703f'];
let ultimoPelo = 0;

// Número al azar entre min y max
function azar(min, max) {
  return min + Math.random() * (max - min);
}

// Convierte la posición del mouse (en la pantalla) a coordenadas del dibujo
function posicion(evento) {
  const p = svg.createSVGPoint();
  p.x = evento.clientX;
  p.y = evento.clientY;
  return p.matrixTransform(svg.getScreenCTM().inverse());
}

// Crea un pelito que sale volando, gira y cae
function crearPelo(x, y, fuerza) {
  const largo = azar(6, 14);
  const curva = azar(-5, 5);
  const pelo = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  pelo.setAttribute('d', `M0 0 q ${largo / 2} ${curva} ${largo} 0`);
  pelo.setAttribute('class', 'pelo');
  pelo.setAttribute('stroke', colores[Math.floor(Math.random() * colores.length)]);
  capa.appendChild(pelo);

  const giroInicial = azar(0, 360);
  const giroFinal = giroInicial + azar(-400, 400);
  const haciaLado = azar(-fuerza, fuerza);   // se va a la izquierda o derecha
  const caida = azar(40, 90) + fuerza;        // cae hacia abajo

  const animacion = pelo.animate(
    [
      { transform: `translate(${x}px, ${y}px) rotate(${giroInicial}deg)`, opacity: 1 },
      { transform: `translate(${x + haciaLado}px, ${y + caida}px) rotate(${giroFinal}deg)`, opacity: 0 }
    ],
    { duration: azar(700, 1300), easing: 'cubic-bezier(.3,.1,.7,1)' }
  );
  animacion.onfinish = () => pelo.remove(); // se borra al terminar
}

// Al MOVER el mouse: caen 2 pelitos (como máximo cada 40 milisegundos)
svg.addEventListener('mousemove', (evento) => {
  const ahora = performance.now();
  if (ahora - ultimoPelo < 40) return;
  ultimoPelo = ahora;
  const p = posicion(evento);
  if (p.y < 0 || p.y > 160) return; // solo dentro del letrero
  for (let i = 0; i < 2; i++) crearPelo(p.x, p.y, 25);
});

// Al hacer CLIC: ¡tijeretazo! salen 25 pelitos volando para todos lados
svg.addEventListener('click', (evento) => {
  const p = posicion(evento);
  if (p.y < 0 || p.y > 160) return;
  for (let i = 0; i < 25; i++) crearPelo(p.x, p.y, 80);
});
